/*
 * A191326  Increasing sequence generated by these rules: a(1)=1, and if x is
 *          in a then [3x/2] and [7x/2] are in a, where [ ]=floor.
 * https://oeis.org/A191326
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 27, u16 n <= 1720, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* 
 * Formula: a(n) is the n‑th term of the set generated by the rules
 *   a(1)=1
 *   if x is in the set then floor(3x/2) and floor(7x/2) are also in it.
 *   The sequence is the increasing arrangement of that set.
 *   The function below returns the n‑th smallest element (n >= 1).
 */
#include <stdlib.h>

/*------------------ internal heap for the pending elements ------------------*/
static seq_t *heap = NULL;            /* heap array (0‑based)                */
static size_t heap_sz = 0;             /* number of elements in the heap     */
static size_t heap_cap = 0;            /* allocated capacity of heap          */

static void heap_grow(void)
{
    size_t new_cap = heap_cap ? heap_cap << 1 : 4;
    seq_t *new_heap = (seq_t *)realloc(heap, new_cap * sizeof(seq_t));
    if (!new_heap) return;            /* allocation failure – ignore      */
    heap = new_heap;
    heap_cap = new_cap;
}

static void heap_push(seq_t val)
{
    if (heap_sz == heap_cap) heap_grow();
    size_t i = heap_sz;
    heap[heap_sz++] = val;
    while (i > 0) {
        size_t parent = (i - 1) >> 1;
        if (heap[parent] <= heap[i]) break;
        seq_t tmp = heap[parent];
        heap[parent] = heap[i];
        heap[i] = tmp;
        i = parent;
    }
}

static seq_t heap_pop(void)
{
    seq_t min = heap[0];
    heap[0] = heap[--heap_sz];
    size_t i = 0;
    while (1) {
        size_t l = (i << 1) + 1;
        if (l >= heap_sz) break;
        size_t r = l + 1;
        size_t smallest = l;
        if (r < heap_sz && heap[r] < heap[l]) smallest = r;
        if (heap[i] <= heap[smallest]) break;
        seq_t tmp = heap[i];
        heap[i] = heap[smallest];
        heap[smallest] = tmp;
        i = smallest;
    }
    return min;
}

/*------------------ cache for already generated terms ---------------------*/
static seq_t *cache = NULL;            /* array of generated terms           */
static size_t cache_sz = 0;            /* number of terms stored             */
static size_t cache_cap = 0;           /* allocated capacity of cache        */
static seq_t last_val = 0;             /* last generated value (for dup canceler) */

static void cache_grow(void)
{
    size_t new_cap = cache_cap ? cache_cap << 1 : 4;
    seq_t *new_cache = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
    if (!new_cache) return;            /* allocation failure – ignore      */
    cache = new_cache;
    cache_cap = new_cap;
}

/*------------------ public function -----------------------------------------*/
seq_t a(idx_t n)
{
    if (n == 0) return 0;              /* behaviour for n=0 is undefined */

    /* Ensure the cache contains at least n terms.  The cache is
       upgraded and terms are generated using a min‑heap. */
    while (cache_sz < (size_t)n) {
        /* Seed the heap with 1 on the first call */
        if (heap_sz == 0) heap_push((seq_t)1);

        /* Pop the smallest candidate */
        seq_t cur = heap_pop();

        /* Skip duplicates – keep only the first occurrence of a value */
        if (cache_sz > 0 && cur == last_val) continue;

        /* Store the new unique value */
        if (cache_sz == cache_cap) cache_grow();
        cache[cache_sz++] = cur;
        last_val = cur;

        /* Push the two successors of cur */
        seq_t child1 = cur + cur/2;          /* floor(3*cur/2) = cur + cur/2   */
        seq_t child2 = cur + cur + child1;   /* floor(7*cur/2) = 2*cur + child1 */

        heap_push(child1);
        heap_push(child2);
    }

    return cache[n-1];
}
